export function Session({
  device = "{{device}}",
  location = "{{location}}",
  lastActive = "{{lastActive}}",
  current = {{current}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 360, padding: "14px 16px", borderRadius: 10, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, border: "1px solid #24143018" }}>
      <div>
        <p style={{ margin: 0, fontWeight: 700, display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
          {device} {current && <span style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".03em", padding: "2px 8px", borderRadius: 999, color: "#14351f", background: accent }}>This device</span>}
        </p>
        <p style={{ margin: "4px 0 0", fontSize: 12, color: "#24143099" }}>{location} &middot; {lastActive}</p>
      </div>
      <button type="button" style={{ flex: "none", padding: "7px 12px", borderRadius: 7, border: "1.5px solid #24143030", background: "none", fontWeight: 700, fontSize: 12, cursor: "pointer" }}>{current ? "Sign out" : "Revoke"}</button>
    </div>
  );
}
